-- WD-487 PoC: 계약 테스트 3종(ReviewItem·NotificationOutbox·ProactiveMessage)이 Tibero 에서 쓰는 테이블만 만든다.
-- TiberoPlatformSchema 가 테스트 계정(FHT_PLATFORM_*)으로 접속해 문장 단위(';' 로 끝나는 줄)로 실행한다. PL/SQL 블록은 쓰지 않는다.
--
-- 타입 매핑(PG → Tibero):
--   BIGSERIAL → NUMBER(19) GENERATED BY DEFAULT AS IDENTITY, BOOLEAN → NUMBER(1), JSONB → JSON(Tibero 7 JSON 타입 — 형식 검사함, setString/getString 왕복 실측),
--   TIMESTAMPTZ → TIMESTAMP(UTC 벽시계 저장 — WD-260 결함 때문에 TSTZ 금지), uuid → VARCHAR2(36), TEXT → VARCHAR2(4000)/CLOB.
--   부분 UNIQUE·NULLS NOT DISTINCT(V134) → NVL(dataset_id, -1) 함수 기반 UNIQUE 인덱스.
-- tenant_id: RLS·GUC 가 없으므로 DEFAULT 없이 문장이 명시로 넣는다(결정 1). FK 는 정리 순서를 단순하게 하려고 두지 않는다.
-- 시각 DEFAULT 규칙(PG 컬럼 타입을 따른다):
--   PG timestamptz(시각 = 순간) → TIMESTAMP + DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP): 세션 시간대와 무관한 UTC 벽시계. 앱은 OffsetDateTime(UTC)
--     으로 쓰고 Tibero 팩토리의 UtcInstantTypeHandler 로 읽는다(notification_outbox 전부).
--   PG timestamp(시간대 없음) → TIMESTAMP + DEFAULT LOCALTIMESTAMP: 세션 시간대 벽시계. PG 의 DEFAULT NOW() 는 timestamp 컬럼에 세션 시간대
--     벽시계를 넣고, pgjdbc·Tibero JDBC 모두 세션 시간대를 JVM 기본 시간대로 연다(Tibero SESSIONTIMEZONE=Asia/Seoul·DBTIMEZONE=UTC 실측).
--     그래서 같은 행에서 앱이 LocalDateTime.now() 로 쓰는 컬럼(graph_review_item.decided_at)과 DEFAULT 컬럼(created_at)이 PG 처럼 같은 기준이다
--     (운영 JVM=UTC 면 둘 다 UTC 벽시계). SYS_EXTRACT_UTC 로 두면 KST JVM 에서 한 행 안에 9시간 차이가 섞인다.

CREATE TABLE tenant (
  id NUMBER(19) PRIMARY KEY,
  slug VARCHAR2(100) NOT NULL,
  status VARCHAR2(16) DEFAULT 'ACTIVE' NOT NULL
);

-- "USER" 는 예약어라 큰따옴표 대문자 식별자로 만든다. 픽스처 SQL 도 "USER" 로 부른다.
CREATE TABLE "USER" (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username VARCHAR2(100) NOT NULL,
  password VARCHAR2(255) NOT NULL,
  name VARCHAR2(100) NOT NULL,
  email VARCHAR2(255)
);

-- 보안 등급(V133). rank 는 함수 이름과 겹치지만 컬럼 이름으로는 쓸 수 있는지 이 DDL 이 확인한다.
CREATE TABLE security_level (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id NUMBER(19) NOT NULL,
  rank NUMBER(10) NOT NULL,
  name VARCHAR2(50) NOT NULL,
  is_default NUMBER(1) DEFAULT 0 NOT NULL,
  allowlist_required NUMBER(1) DEFAULT 0 NOT NULL,
  admin_bypass NUMBER(1) DEFAULT 0 NOT NULL,
  ai_policy VARCHAR2(16) DEFAULT 'ALL' NOT NULL,
  share_policy VARCHAR2(16) DEFAULT 'ALLOW' NOT NULL
);

-- 기본 4등급 시드(V133) — 테스트 기본 테넌트(1)만.
INSERT INTO security_level (tenant_id, rank, name, is_default, allowlist_required, admin_bypass, ai_policy, share_policy)
  VALUES (1, 1, '공개', 0, 0, 0, 'ALL', 'ALLOW');
