  VALUES (1, 4, '기밀', 0, 1, 0, 'SELF_HOSTED_ONLY', 'DENY');
COMMIT;

-- 역할·부여(등급 자격 계산 — 테스트용 ClearanceResolver 스텁이 읽는다).
CREATE TABLE role (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id NUMBER(19) NOT NULL,
  name VARCHAR2(100) NOT NULL,
  max_security_level_id NUMBER(19)
);

CREATE TABLE user_role (
  user_id NUMBER(19) NOT NULL,
  role_id NUMBER(19) NOT NULL,
  tenant_id NUMBER(19) NOT NULL
);

-- 가시성 조각이 읽는 데이터셋·허용 목록(가시성 필요한 컬럼만).
CREATE TABLE dataset (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id NUMBER(19) NOT NULL,
  security_level_id NUMBER(19) NOT NULL
);

CREATE TABLE dataset_access_grant (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id NUMBER(19) NOT NULL,
  dataset_id NUMBER(19) NOT NULL,
  user_id NUMBER(19),
  role_id NUMBER(19)
);

-- 검수 항목(V76·V102·V134).
CREATE TABLE graph_review_item (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id NUMBER(19) NOT NULL,
  item_type VARCHAR2(40) NOT NULL,
  status VARCHAR2(20) DEFAULT 'pending' NOT NULL,
  dataset_id NUMBER(19),
  signal_type VARCHAR2(40),
  signal_score BINARY_DOUBLE,
  reason VARCHAR2(4000),
  payload JSON NOT NULL,
  dedupe_key VARCHAR2(512) NOT NULL,
  decided_by NUMBER(19),
  decided_at TIMESTAMP,
  created_at TIMESTAMP DEFAULT LOCALTIMESTAMP NOT NULL -- PG timestamp DEFAULT NOW() → 세션 시간대 벽시계(머리말 규칙)
);

-- V134 의 (tenant_id, item_type, dataset_id, dedupe_key) NULLS NOT DISTINCT 를 함수 기반 UNIQUE 로 흉내 낸다.
CREATE UNIQUE INDEX uq_graph_review_item ON graph_review_item (tenant_id, item_type, NVL(dataset_id, -1), dedupe_key);

-- 알림 outbox(V50·V103).
CREATE TABLE notification_outbox (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id NUMBER(19) NOT NULL,
  idempotency_key VARCHAR2(64) NOT NULL,
  correlation_id VARCHAR2(36) NOT NULL,
  event_type VARCHAR2(64) NOT NULL,
  event_source_id NUMBER(19),
  channel_type VARCHAR2(32) NOT NULL,
  recipient_user_id NUMBER(19),
  recipient_address VARCHAR2(4000),
  payload_ref_type VARCHAR2(32),
  payload_ref_id NUMBER(19),
  payload JSON,
  payload_type VARCHAR2(16) DEFAULT 'STANDARD' NOT NULL,
  status VARCHAR2(32) DEFAULT 'PENDING' NOT NULL, -- V105 가 32 로 넓혔다(PERMANENT_FAILURE 17자)
  attempt_count NUMBER(10) DEFAULT 0 NOT NULL,
  next_attempt_at TIMESTAMP DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL, -- PG timestamptz → UTC 벽시계(머리말 규칙)
  claimed_at TIMESTAMP,
  claimed_by VARCHAR2(64),
  sent_at TIMESTAMP,
  last_error VARCHAR2(4000),
  last_error_at TIMESTAMP,
  permanent_failure_reason VARCHAR2(64),
  created_at TIMESTAMP DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL,
  CONSTRAINT uk_outbox_idempotency UNIQUE (tenant_id, idempotency_key) -- V106: 테넌트마다 같은 멱등 키를 쓸 수 있다
);

-- 프로액티브 작업·실행·메시지(V42·V103 + 실행 security_level_id).
CREATE TABLE proactive_job (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id NUMBER(19) NOT NULL,
  user_id NUMBER(19) NOT NULL,
  name VARCHAR2(200) NOT NULL
);

CREATE TABLE proactive_job_execution (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id NUMBER(19) NOT NULL,
  job_id NUMBER(19) NOT NULL,
  status VARCHAR2(50) DEFAULT 'PENDING' NOT NULL,
  security_level_id NUMBER(19)
);

CREATE TABLE proactive_message (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id NUMBER(19) NOT NULL,
  user_id NUMBER(19) NOT NULL,
  execution_id NUMBER(19),
  title VARCHAR2(500) NOT NULL,
  content JSON NOT NULL,
  message_type VARCHAR2(100) DEFAULT 'REPORT' NOT NULL,
  read NUMBER(1) DEFAULT 0 NOT NULL,
  read_at TIMESTAMP,
  created_at TIMESTAMP DEFAULT LOCALTIMESTAMP -- PG timestamp DEFAULT NOW() → 세션 시간대 벽시계(머리말 규칙)
);
